 {error&&<div className="cp-alert error" role="alert" data-testid="customer-project-load-error">{error}<Button size="sm" variant="outline" disabled={loading||busy||followupBusy} onClick={refresh}>重试加载项目</Button></div>}{notice&&<div className="cp-alert success" role="status">{notice}</div>}{loading&&hasLoaded&&<div className="cp-loading" role="status">正在刷新客户项目资料…</div>}{financeLoading&&<div className="cp-loading" role="status" data-testid="customer-project-finance-status">正在读取项目财务资料…</div>}{financeError&&<div className="cp-readonly" role="status" data-testid="customer-project-finance-error">项目财务资料暂未更新：{financeError}<Button size="sm" variant="outline" disabled={financeLoading||busy||followupBusy} onClick={()=>void loadFinance()}>重试财务资料</Button></div>}
